files.agent-pane/theme.css:
/* Tachyon's chat: output as command blocks. Your prompt is a selected block (a teal ring around a
   faint teal wash, nearly square corners), tool calls and cards are raised graphite blocks with a
   light edge, secondary text is the cool gray of a prompt line, and links take the accent.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent, --agent-page-bg), so it reads over Tachyon and
   Tachyon Light and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-accent) 9%, transparent);
  --cv-user-bubble-edge: color-mix(in srgb, var(--agent-accent) 70%, transparent);
  --cv-user-bubble-radius: 4px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 14%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 76%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 65%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 88%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 88%, var(--agent-text));

  /* Pending cmux#46846 (--menu-*): a terminal's block and context menus. Inert until it lands.
     An opaque panel in the page's own tone with 4 px corners and a light hairline, 30 px rows
     that run nearly edge to edge (a 4 px inset, 2 px highlight corners), the highlighted row in
     the accent at 22% (the file picker's selected row), shortcuts and section labels in the gray
     of a prompt line, separators inset 8 px, and submenus that meet their row. */
  --menu-radius: 4px;
  --menu-padding: 4px;
  --menu-fill: color-mix(in srgb, var(--agent-page-bg) 97%, var(--agent-text));
  --menu-border: color-mix(in srgb, var(--agent-text) 16%, transparent);
  --menu-row-height: 30px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-accent) 22%, transparent);
  --menu-hover-radius: 2px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 14%, transparent);
  --menu-separator-inset: 8px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 74%, transparent);
  --menu-label-weight: 500;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 74%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 74%, transparent);
  --menu-disabled-opacity: 0.4;
  --menu-submenu-offset: 2px;
  --menu-submenu-align-offset: -4px;
}

